// Parse one normalized Meta WhatsApp payload. WF22 is the sole active Meta ingress.
const item = $input.first().json || {};
const body = item.body || {};
const entry = (body.entry && body.entry[0]) || {};
const change = (entry.changes && entry.changes[0]) || {};
const value = change.value || {};
if (value.statuses) return [{ json: { _action: 'ignore', reason: 'status_event' } }];
const msg = value.messages && value.messages[0];
if (!msg) return [{ json: { _action: 'ignore', reason: 'no_message' } }];
const phone = msg.from || '';
let text = '';
let interactive_id = '';
const message_type = String(msg.type || '');
if (message_type === 'text' && msg.text) text = msg.text.body || '';
else if (message_type === 'button' && msg.button) { text = msg.button.text || ''; interactive_id = msg.button.payload || ''; }
else if (message_type === 'interactive' && msg.interactive) {
  const it = msg.interactive;
  text = (it.button_reply && it.button_reply.title) || (it.list_reply && it.list_reply.title) || '';
  interactive_id = (it.button_reply && it.button_reply.id) || (it.list_reply && it.list_reply.id) || '';
} else return [{ json: { _action: 'ignore', reason: 'unsupported_message_type' } }];
const contact = (value.contacts && value.contacts[0]) || {};
const pushName = (contact.profile && contact.profile.name) || '';
const messageId = msg.id || '';
const context_id = msg.context && msg.context.id ? String(msg.context.id) : null;
const timestamp = msg.timestamp ? parseInt(msg.timestamp, 10) : Math.floor(Date.now() / 1000);
return [{ json: { _action: 'process', phone, text: String(text).trim(), interactive_id: String(interactive_id).trim(), message_type, context_id, reply_to_wamid: context_id, wamid: messageId, pushName, messageId, timestamp, remoteJid: phone } }];

// Route normalized messages. V3 claims require a Meta button payload; V2 remains drain-only.
const parsed = $('Parse Evolution Payload').first().json;
const db = $input.first().json;
if (!db.new_message_id && db.new_message_id !== 0) return [{ json: { route: 'ignore', reason: 'duplicate_message' } }];
const phone = parsed.phone, text = parsed.text, pushName = parsed.pushName, messageId = parsed.messageId;
if (db.is_agent) {
  const v3ClaimMatch = parsed.message_type === 'button' ? String(parsed.interactive_id || '').match(/^claim:v3:(\\d+):(\\d+)$/) : null;
  if (v3ClaimMatch) {
    const opportunityId = Number(v3ClaimMatch[1]), attemptId = Number(v3ClaimMatch[2]);
    if (!Number.isSafeInteger(opportunityId) || opportunityId <= 0 || !Number.isSafeInteger(attemptId) || attemptId <= 0) return [{ json: { route: 'ignore', reason: 'invalid_v3_claim_payload' } }];
    return [{ json: { route: 'agent_claim', claim_version: 'v3', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, opportunity_id: opportunityId, attempt_id: attemptId, routing_tier: null, context_id: parsed.context_id || null, reply_to_wamid: parsed.context_id || null, wamid: messageId, raw_message: parsed.interactive_id, messageId } }];
  }
  const claimMatch = String(parsed.interactive_id || '').match(/^claim:(\\d+):(owner|primary_guard|backup_guard)$/);
  if (claimMatch) {
    const opportunityId = Number(claimMatch[1]);
    if (!Number.isSafeInteger(opportunityId) || opportunityId <= 0) return [{ json: { route: 'ignore', reason: 'invalid_v2_claim_payload' } }];
    return [{ json: { route: 'agent_claim', claim_version: 'v2_drain', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, opportunity_id: opportunityId, routing_tier: claimMatch[2], context_id: parsed.context_id || null, reply_to_wamid: parsed.context_id || null, wamid: messageId, raw_message: parsed.interactive_id, messageId } }];
  }
  const textClaimMatch = String(text || '').trim().match(/^TOMO-V2-(\\d+)-(O|P|B)$/i);
  if (textClaimMatch) {
    const opportunityId = Number(textClaimMatch[1]);
    if (!Number.isSafeInteger(opportunityId) || opportunityId <= 0) return [{ json: { route: 'ignore', reason: 'invalid_v2_claim_text' } }];
    const tierByCode = { O: 'owner', P: 'primary_guard', B: 'backup_guard' };
    return [{ json: { route: 'agent_claim', claim_version: 'v2_drain', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, opportunity_id: opportunityId, routing_tier: tierByCode[textClaimMatch[2].toUpperCase()], context_id: parsed.context_id || null, reply_to_wamid: parsed.context_id || null, wamid: messageId, raw_message: text, messageId } }];
  }
  const tomoMatch = String(text || '').match(/^TOMO-([A-Z0-9]{4})$/i);
  if (tomoMatch) return [{ json: { route: 'agent_claim', claim_version: 'v2_drain', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, short_code: tomoMatch[1].toUpperCase(), context_id: parsed.context_id || null, reply_to_wamid: parsed.context_id || null, wamid: messageId, raw_message: text, messageId } }];
  return [{ json: { route: 'agent_followup_reply', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, text, messageId } }];
}
if (!db.conversation_id) return [{ json: { route: 'new_lead', phone, pushName, text, messageId } }];
const mode = db.conv_mode;
if (mode === 'ai') return [{ json: { route: 'ai_conversation', conversation_id: db.conversation_id, phone, pushName, text, messageId, current_property: db.current_property, assigned_agent_id: db.assigned_agent_id } }];
if (mode === 'human') return [{ json: { route: 'human_forward', conversation_id: db.conversation_id, phone, pushName, text, messageId, assigned_agent_id: db.assigned_agent_id, assigned_agent_phone: db.assigned_agent_phone } }];
if (mode === 'pending_assignment') return [{ json: { route: 'pending', conversation_id: db.conversation_id, phone, pushName, text, messageId } }];
return [{ json: { route: 'ignore', reason: 'unknown_mode' } }];

// Forward lead message to assigned agent via Evolution.
// In human mode, the bot acts as a relay.
const data = $input.first().json;

const forwardBody = [
  `Mensaje de ${data.pushName || 'Lead'} (${data.phone}):`,
  ``,
  data.text
].join('\n');

return [{
  json: {
    number: data.assigned_agent_phone,
    text: forwardBody,
    conversation_id: data.conversation_id,
    phone: data.phone
  }
}];

