const crypto=require('crypto');
const item=$input.first(); const headers=item.json.headers||{}; const signature=String(headers['x-hub-signature-256']||headers['X-Hub-Signature-256']||'');
const encoded=item.binary?.data?.data; const secret=$env.WA_WEBHOOK_SECRET;
if(typeof encoded!=='string'||!secret||!signature.startsWith('sha256=')) throw new Error('invalid webhook signature');
const raw=Buffer.from(encoded,'base64'); const expected='sha256='+crypto.createHmac('sha256',secret).update(raw).digest('hex'); const a=Buffer.from(signature),b=Buffer.from(expected);
if(a.length!==b.length||!crypto.timingSafeEqual(a,b)) throw new Error('invalid webhook signature');
return [{json:{body:JSON.parse(raw.toString('utf8'))}}];

const body=$input.first().json.body;
const value=body.entry?.[0]?.changes?.[0]?.value||{};
const s=value.statuses?.[0]||{};
const message_id=String(s.id||''); const status=String(s.status||'');
if(!message_id||!['sent','delivered','failed'].includes(status)) return [{json:{valid:false}}];
const ts=Number(s.timestamp); const evidence={status};
if(Array.isArray(s.errors)) evidence.error_codes=s.errors.map(e=>String(e.code||'')).filter(Boolean).slice(0,5);
return [{json:{valid:true,message_id,status,provider_timestamp:Number.isFinite(ts)?new Date(ts*1000).toISOString():null,evidence}}];

// Parse authenticated Meta Cloud API inbound message.
const body=$input.first().json.body||{}; const value=body.entry?.[0]?.changes?.[0]?.value||{}; const msg=value.messages?.[0];
if(!msg) return [{json:{_action:'ignore',reason:'no_message'}}];
let text=msg.text?.body||msg.button?.text||''; let interactive_id='';
if(msg.interactive?.button_reply){text=msg.interactive.button_reply.title||'';interactive_id=msg.interactive.button_reply.id||'';}
else if(msg.interactive?.list_reply){text=msg.interactive.list_reply.title||'';interactive_id=msg.interactive.list_reply.id||'';}
if(!text&&!interactive_id) return [{json:{_action:'ignore',reason:'unsupported_message_type'}}];
const phone=String(msg.from||''); const contact=value.contacts?.[0]||{};
return [{json:{_action:'process',phone,text:String(text).trim(),interactive_id,pushName:contact.profile?.name||'',messageId:String(msg.id||''),timestamp:Number(msg.timestamp)||Math.floor(Date.now()/1000),remoteJid:phone}}];

// Route deduplicated inbound messages and bind claims to opportunity+tier.
const parsed = $('Parse Evolution Payload').first().json;
const db = $input.first().json;
if (!db.new_message_id && db.new_message_id !== 0) return [{ json: { route: 'ignore', reason: 'duplicate_message' } }];
const { phone, text, pushName, messageId } = parsed;
if (db.is_agent) {
  const claim = String(parsed.interactive_id || '').match(/^claim:(\d+):(owner|primary_guard|backup_guard)$/);
  if (claim) return [{ json: { route: 'agent_claim', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, opportunity_id: Number(claim[1]), routing_tier: claim[2], button_id: parsed.interactive_id, raw_message: text, messageId } }];
  const legacy = text.match(/^TOMO-([A-Z0-9]{4})$/i);
  if (legacy) return [{ json: { route: 'agent_claim', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, short_code: legacy[1].toUpperCase(), raw_message: text, messageId } }];
  return [{ json: { route: 'agent_followup_reply', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, text, messageId } }];
}
if (!db.conversation_id) return [{ json: { route: 'new_lead', phone, pushName, text, messageId } }];
const common = { conversation_id: db.conversation_id, phone, pushName, text, messageId };
if (db.conv_mode === 'ai') return [{ json: { route: 'ai_conversation', ...common, current_property: db.current_property, assigned_agent_id: db.assigned_agent_id } }];
if (db.conv_mode === 'human') return [{ json: { route: 'human_forward', ...common, assigned_agent_id: db.assigned_agent_id, assigned_agent_phone: db.assigned_agent_phone } }];
if (db.conv_mode === 'pending_assignment') return [{ json: { route: 'pending', ...common } }];
return [{ json: { route: 'ignore', reason: 'unknown_mode' } }];

// Forward lead message to assigned agent via Evolution.
// In human mode, the bot acts as a relay.
const data = $input.first().json;

const forwardBody = [
  `Mensaje de ${data.pushName || 'Lead'} (${data.phone}):`,
  ``,
  data.text
].join('\n');

return [{
  json: {
    number: data.assigned_agent_phone,
    text: forwardBody,
    conversation_id: data.conversation_id,
    phone: data.phone
  }
}];

